package in.jharkhand.civic.controller;
import in.jharkhand.civic.repository.JsonStore; import in.jharkhand.civic.service.WorkflowService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/industry") public class IndustryController {private final JsonStore s;private final WorkflowService w;public IndustryController(JsonStore s,WorkflowService w){this.s=s;this.w=w;}@GetMapping("/opportunities") List<Map<String,Object>> opp(){return s.read("projects.json").stream().filter(p->Set.of("COLLABORATION_OPEN","TEAM_FORMED","RESEARCH","PROTOTYPE","FIELD_TESTING").contains(p.get("status"))).toList();}@PostMapping("/{id}/apply") Map<String,Object> apply(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){Map<String,Object>x=new LinkedHashMap<>(r);x.put("industryId",id);return w.collaboration(a.getName(),String.valueOf(r.get("projectId")),x);}@PostMapping("/projects/{id}/invite") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> invite(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){return w.collaboration(a.getName(),id,r);}}
